package com.primehr.learningdevelopment.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.math.BigDecimal;import java.util.Objects;
@Entity @Table(name="ld_evaluation_level",uniqueConstraints={@UniqueConstraint(name="uk_ld_evaluation_level_type",columnNames={"agency_id","framework_version_id","level_type"}),@UniqueConstraint(name="uk_ld_evaluation_level_order",columnNames={"agency_id","framework_version_id","display_order"})})
public class LdEvaluationLevel extends RspAuditedEntity {
 public enum Type{REACTION,LEARNING,BEHAVIOR_APPLICATION,RESULTS,RETURN_OF_EXPECTATION}public enum ScoreMethod{QUALITATIVE,PERCENTAGE,POINTS,PASS_FAIL}
 @Column(name="framework_version_id",nullable=false,length=36)private String frameworkVersionId;@Enumerated(EnumType.STRING)@Column(name="level_type",nullable=false,length=30)private Type levelType;@Column(nullable=false)private boolean required;@Column(name="due_after_days",nullable=false)private int dueAfterDays;@Enumerated(EnumType.STRING)@Column(name="score_method",nullable=false,length=20)private ScoreMethod scoreMethod;@Column(name="passing_score",precision=19,scale=6)private BigDecimal passingScore;@Column(name="evidence_requirements",nullable=false,length=3000)private String evidenceRequirements;@Column(name="instrument_guidance",nullable=false,length=3000)private String instrumentGuidance;@Column(name="display_order",nullable=false)private int displayOrder;
 protected LdEvaluationLevel(){}public LdEvaluationLevel(String agency,String framework,Type type,boolean required,int days,ScoreMethod method,BigDecimal score,String evidence,String guidance,int order){super(agency);frameworkVersionId=requiredText(framework,"frameworkVersionId");levelType=Objects.requireNonNull(type,"levelType");if(days<0)throw new IllegalArgumentException("dueAfterDays cannot be negative");if(order<1)throw new IllegalArgumentException("displayOrder must be positive");scoreMethod=Objects.requireNonNull(method,"scoreMethod");if((method==ScoreMethod.PERCENTAGE||method==ScoreMethod.POINTS)&&score==null)throw new IllegalArgumentException("passingScore is required for numeric scoring");if(score!=null&&score.signum()<0)throw new IllegalArgumentException("passingScore cannot be negative");this.required=required;dueAfterDays=days;passingScore=score;evidenceRequirements=requiredText(evidence,"evidenceRequirements");instrumentGuidance=requiredText(guidance,"instrumentGuidance");displayOrder=order;}
 public String getFrameworkVersionId(){return frameworkVersionId;}public Type getLevelType(){return levelType;}public boolean isRequired(){return required;}public int getDueAfterDays(){return dueAfterDays;}public ScoreMethod getScoreMethod(){return scoreMethod;}public BigDecimal getPassingScore(){return passingScore;}public String getEvidenceRequirements(){return evidenceRequirements;}public String getInstrumentGuidance(){return instrumentGuidance;}public int getDisplayOrder(){return displayOrder;}
}
